good.code:
app.post('/payments', async (req, res) => {
  const key = req.get('Idempotency-Key')
  if (!key) return res.status(400).json({ error: 'Idempotency-Key required' })
  const hash = fingerprint(req.body)
  const claimed = await keys.claim(req.account, key, hash) // unique (account, key)
  if (!claimed) {
    const saved = await keys.get(req.account, key)
    if (saved.hash !== hash) return res.status(422).json({ error: 'key reused with a different body' })
    if (saved.state === 'in_progress') return res.status(409).json({ error: 'request in progress' })
    return res.status(saved.status).json(saved.body)
  }
  const payment = await charge(req.body)
  await keys.complete(req.account, key, 201, payment)
  res.status(201).json(payment)
})

